import fs from 'node:fs';
const [source,output,secret]=process.argv.slice(2);
if(fs.readFileSync(source,'utf8')!=='fixed source')throw Error('read failed');
let deniedRead=false,deniedWrite=false;
try{fs.readFileSync(secret);}catch(e){deniedRead=['EPERM','EACCES'].includes(e.code);}
try{fs.writeFileSync(source,'forbidden');}catch(e){deniedWrite=['EPERM','EACCES'].includes(e.code);}
if(!deniedRead||!deniedWrite)throw Error('boundary failed');
fs.writeFileSync(output,'fixed output');
console.log(JSON.stringify({node:process.version,deniedRead,deniedWrite}));
